import{_ as a,c as t,o as r,aj as i}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Water","description":"","frontmatter":{"title":"Water"},"headers":[],"relativePath":"ingredients/water.md","filePath":"ingredients/water.md"}'),l={name:"ingredients/water.md"};function n(o,e,s,d,h,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="water" tabindex="-1">Water <a class="header-anchor" href="#water" aria-label="Permalink to “Water”">​</a></h1><p>Water is more than &quot;just water.&quot; It wakes up fermentation, hydrates starch and gluten, and sets the tone for how tight or stretchy your dough feels. Hydration percentage is one of the most important baker&#39;s-percentage levers you can control.</p><h2 id="why-water-quality-matters" tabindex="-1">Why Water Quality Matters <a class="header-anchor" href="#why-water-quality-matters" aria-label="Permalink to “Why Water Quality Matters”">​</a></h2><h3 id="filtered-water-recommended" tabindex="-1"><strong>Filtered Water (Recommended)</strong> <a class="header-anchor" href="#filtered-water-recommended" aria-label="Permalink to “Filtered Water (Recommended)”">​</a></h3><ul><li>More neutral flavor</li><li>No chlorine to slow fermentation</li><li>More consistent dough texture</li></ul><h3 id="tap-water" tabindex="-1"><strong>Tap Water</strong> <a class="header-anchor" href="#tap-water" aria-label="Permalink to “Tap Water”">​</a></h3><ul><li>Safe and totally usable</li><li>Chlorine may <em>slightly</em> reduce yeast activity</li><li>Hardness varies by location, which impacts dough feel</li></ul><p>If in doubt: <strong>filtered is ideal</strong>, but tap works fine for everyday baking.</p><hr><h2 id="hydration" tabindex="-1">Hydration <a class="header-anchor" href="#hydration" aria-label="Permalink to “Hydration”">​</a></h2><p>Hydration percentage controls:</p><ul><li>Stickiness</li><li>Open crumb</li><li>Oven spring</li><li>Dough handling</li></ul><hr><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><ul><li>Warmer water speeds fermentation; colder water slows it.</li><li>If dough is tearing instead of stretching, increase hydration by <strong>1-2%</strong>.</li><li>For whole wheat doughs, increase hydration <strong>4-8%</strong>.</li><li>Match water temperature to your timeline: warm for same-day dough, cooler for long ferments.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/ingredients/yeast.html">Yeast</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li></ul>',17)])])}const f=a(l,[["render",n]]);export{u as __pageData,f as default};
